### Finite State Machine (FSM) Implementation

Next, create a script that implements the FSM. The FSM will manage the player's states, such as walking, running, jumping, and attacking.

```gdscript
enum EState { WALK, RUN, JUMP, ATTACK }

class Player:
    var state_machine = Node.new()

    func _init():
        state_machine = Node.new()

    func _ready():
        state_machine = StateMachine.new()
        state_machine.connect("state_changed", self, "_on_state_changed")

    func _process(delta):
        state_machine.update(delta)

    func move(delta, speed):
        state_machine.move(delta, speed)

    func jump():
        state_machine.jump()

    func attack():
        state_machine.attack()

    func _on_state_changed(new_state):
        if new_state == EState.WALK:
            $AnimationPlayer.play("Walk")
        elif new_state == EState.RUN:
            $AnimationPlayer.play("Run")
        elif new_state == EState.JUMP:
            $AnimationPlayer.play("Jump")
        elif new_state == EState.ATTACK:
            $AnimationPlayer.play("Attack")
```

The FSM (`StateMachine`) class will manage the player's state transitions:

```gdscript
class StateMachine:
    signal state_changed(new_state)

    var current_state = 0
    var states = [EState.WALK, EState.RUN, EState.JUMP, EState.ATTACK]

    func update(delta):
        # Update the current state
        current_state = current_state

    func move(delta, speed):
        # Change state based on speed
        if speed > 5:
            if current_state!= EState.RUN:
                current_state = EState.RUN
                emit_signal("state_changed", current_state)
        elif speed < -5:
            if current_state!= EState.WALK:
                current_state = EState.WALK
                emit_signal("state_changed", current_state)
        elif speed == 0:
            if current_state!= EState.JUMP:
                current_state = EState.JUMP
                emit_signal("state_changed", current_state)

    func jump():
        # Change state to JUMP
        if current_state!= EState.JUMP:
            current_state = EState.JUMP
            emit_signal("state_changed", current_state)

    func attack():
        # Change state to ATTACK
        if current_state!= EState.ATTACK:
            current_state = EState.ATTACK
            emit_signal("state_changed", current_state)
```

